#!/bin/sh
# build.sh --target dev|prod [--out DIR]
set -e
target=dev; out=dist
while [ $# -gt 0 ]; do
  case $1 in
  --target) target=$2; shift 2 ;;
  --out) out=$2; shift 2 ;;
  *) echo "unknown flag: $1" >&2; exit 2 ;;
  esac
done
mkdir -p "$out"
echo "built $target" > "$out/BUILD"
#!/bin/sh
rm -rf dist release release.tgz
